import { test, expect } from '@playwright/test';

test.describe('Active Filter Tags Display', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should display active filter tags above search results when filters are applied', async ({ page }) => {
    // Apply first filter using getByRole
    const searchInput = page.getByRole('textbox', { name: /search/i });
    await searchInput.fill('playwright');

    // Apply first filter using getByRole
    const filterButton = page.getByRole('button', { name: /filter by category/i });
    await filterButton.click();

    // Verify first filter tag appears
    const filterTag = page.getByText('Category');
    await expect(filterTag).toBeVisible();

    // Apply second filter using getByRole
    const secondFilterButton = page.getByRole('button', { name: /filter by price/i });
    await secondFilterButton.click();

    // Verify second filter tag appears
    const secondFilterTag = page.getByText('Price');
    await expect(secondFilterTag).toBeVisible();

    // Verify active filter tag is highlighted
    const activeFilterTag = page.getByText('Category');
    await expect(activeFilterTag).toBeVisible();
    await expect(activeFilterTag).toHaveClass(/active/i);

    // Verify results are displayed
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();

    // Verify results contain expected items
    const resultItem = page.getByText('Playwright Test Script');
    await expect(resultItem).toBeVisible();

    // Verify filter tags are displayed above results
    const filterTagsContainer = page.getByRole('region', { name: /filter tags/i });
    await expect(filterTagsContainer).toBeVisible();

    // Verify filter tags are displayed in correct order
    const firstFilterTag = page.getByText('Category');
    const secondFilterTag = page.getByText('Price');
    await expect(firstFilterTag).toBeVisible();
    await expect(secondFilterTag).toBeVisible();
  });

  test('should clear all filters and hide filter tags when clear button is clicked', async ({ page }) => {
    // Apply first filter using getByRole
    const searchInput = page.getByRole('textbox', { name: /search/i });
    await searchInput.fill('playwright');

    // Apply first filter using getByRole
    const filterButton = page.getByRole('button', { name: /filter by category/i });
    await filterButton.click();

    // Verify first filter tag appears
    const filterTag = page.getByText('Category');
    await expect(filterTag).toBeVisible();

    // Apply second filter using getByRole
    const secondFilterButton = page.getByRole('button', { name: /filter by price/i });
    await secondFilterButton.click();

    // Verify second filter tag appears
    const secondFilterTag = page.getByText('Price');
    await expect(secondFilterTag).toBeVisible();

    // Click clear button using getByRole
    const clearButton = page.getByRole('button', { name: /clear filters/i });
    await clearButton.click();

    // Verify filter tags are hidden
    const filterTagsContainer = page.getByRole('region', { name: /filter tags/i });
    await expect(filterTagsContainer).not.toBeVisible();

    // Verify results are displayed without filters
    const resultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(resultsContainer).toBeVisible();

    // Verify results contain expected items
    const resultItem = page.getByText('Playwright Test Script');
    await expect(resultItem).toBeVisible();
  });
});
